command:
// ==========================================
// LUNAS WIRKUNG: NURTIS SCHALE (NURTI)
//
// - Ziel: eigene Schale oder eigenes Gefäß
// - nur eine aktive Schale gleichzeitig
// - Kochen: mindestens +1 FW, kaufmännisch QS/2
// - Giftstufe in enthaltenen Lebensmitteln: −Bonus
// - beide Textänderungen: Selbsterstellt (0)
// - Dauer: bis zur nächsten Vollmondnacht
// - Effektanlage über Block 6
// - Wirkungsende über Block 7
// - öffentliche Gabenkarte über Block 11
// ==========================================

(async function () {

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt =
    !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
    !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) {
        return ui.notifications.error(
            "Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!"
        );
    }

    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;

if (
    !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen
) {
    return ui.notifications.error(
        "Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!"
    );
}

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Nurtis Schale", vollerName = "Nurtis Schale (Nurti)", ahne = "Nurti";
const endeKey = "nurtisschale";
const dauerText = "Bis zur nächsten Vollmondnacht";
const endeText =
    "Die Schale verliert ihren übernatürlichen Zustand und wird wieder zu einem ganz normalen Behältnis. Nurtis schützende Hand ruht.";

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) {
        await actor.unsetFlag("world", "letzteGabenQS");
    }

    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) {
        await actor.unsetFlag("world", "letzteGabenMessageId");
    }
};

const findeBehaeltnisse = actor =>
    (actor?.items || [])
        .filter(item => {
            if (!["equipment", "consumable", "loot"].includes(item.type)) return false;

            const name = String(item.name || "").toLowerCase();

            return (
                name.includes("schale") ||
                name.includes("gefäß") ||
                name.includes("gefaess")
            );
        })
        .sort((a, b) =>
            String(a.name).localeCompare(String(b.name), "de")
        );

const findeSchalenEffekte = actor =>
    (actor?.effects || []).filter(effect =>
        effect.getFlag("dsk", "isNurtisSchale") === true &&
        effect.getFlag("dsk", "casterUuid") === actor.uuid
    );

// +++ 4 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++++++

let casterActor =
    canvas.tokens.controlled[0]?.actor ||
    game.user.character ||
    null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables
            .map(token => token.actor)
            .find(actor =>
                actor?.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
        game.actors.find(actor =>
            actor.getFlag("world", "letzteGabenQS") !== undefined
        ) ||
        null;
}

if (!casterActor) {
    return ui.notifications.warn(
        "Luna sagt 🌙: Bitte wähle zuerst deinen Token aus, liebes Nurtikind!"
    );
}

if (!game.user.isGM && !casterActor.isOwner) {
    return ui.notifications.warn(
        "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
    );
}

const casterToken = DSK_FW.Token.Finde(casterActor);

if (!casterToken) {
    return ui.notifications.warn(
        "Luna sagt 🌙: Kein Token des Wirkenden gefunden!"
    );
}

const casterName = DSK_FW.ResolveTokenName(casterActor);

const rollData =
    typeof testData !== "undefined" && testData
        ? testData
        : typeof args !== "undefined" && args[0]
            ? args[0]
            : null;

const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor,
    gabenName,
    suchbegriffe: [
        "Nurtis Schale Probe",
        "Nurtis Schale",
        "Nurti Schale"
    ],
    testDataObj: rollData,
    fallback: 0,
    protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung:
            "Nurtis schützende Macht konnte das Behältnis nicht durchdringen.",
        wirkender: casterName,
        ziele: [],
        misserfolge: [{ name: casterName }],
        dauerText: "Keine Wirkung",
        gmBereich: false,
        angewendet: true,
        erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 5 - BEHÄLTNISWAHL +++++++++++++++++++++++++++++++++++++++

const behaeltnisse = findeBehaeltnisse(casterActor);

if (!behaeltnisse.length) {
    await raeumeQSAuf(casterActor);

    return ui.notifications.warn(
        "Luna sagt 🌙: Keine Schale und kein Gefäß im Inventar gefunden!"
    );
}

const bonus = Math.max(1, Math.round(qs / 2));

const wirkungText =
    `Die Macht Nurtis durchströmt das gewählte Behältnis.` +
    `<br><br>Das Nurtikind erhält <b>+${bonus} FW</b> auf <i>Kochen</i> ` +
    `<span style="font-size:.85em;font-weight:normal;">(${qs} QS/2)</span>.` +
    `<br>Die Stufe von Giften in darin befindlichen Nahrungsmitteln sinkt um <b>${bonus} Stufe(n)</b>.` +
    `<br>Es kann nur eine geweihte Schale gleichzeitig bestehen.`;

const optionen = behaeltnisse
    .map(item =>
        `<option value="${item.id}">${item.name}</option>`
    )
    .join("");

const itemId = await foundry.applications.api.DialogV2.wait({
    window: { title: gabenName },
    position: { width: 420 },

    content: `<form>
        ${DSK_FW.UI.Header(vollerName, DSK_FW.Symbol(ahne))}

        <div class="dskbox2" style="margin-top:10px;">
            <p style="font-size:.95em;line-height:1.35;">
                ${wirkungText}
            </p>

            <div style="margin-top:10px;">
                <label style="font-weight:bold;font-size:.9em;">
                    Wähle dein Behältnis:
                </label>

                <select name="gegenstandId"
                    style="width:100%;padding:4px;margin-top:4px;">
                    ${optionen}
                </select>
            </div>

            <hr>

            <p style="text-align:center;font-weight:bold;">
                Wirkungsdauer:<br>${dauerText}
            </p>
        </div>
    </form>`,

    buttons: [
        {
            action: "anwenden",
            label: "Gabe wirken",
            icon: "fas fa-magic",
            default: true,

            callback: event => {
                const form = event.target.closest("form");

                return form
                    ? String(
                        new FormData(form).get("gegenstandId") || ""
                    ).trim() || null
                    : null;
            }
        },
        {
            action: "abbrechen",
            label: "Abbrechen",
            icon: "fas fa-times",
            callback: () => null
        }
    ],

    rejectClose: false
});

if (!itemId) {
    await raeumeQSAuf(casterActor);
    return;
}

const behaeltnis = casterActor.items.get(itemId);

if (
    !behaeltnis ||
    !behaeltnisse.some(item => item.id === behaeltnis.id)
) {
    await raeumeQSAuf(casterActor);

    return ui.notifications.error(
        "Luna sagt 🌙: Das ausgewählte Behältnis wurde nicht gefunden!"
    );
}

// +++ 6 - ALTE SCHALE ENTFERNEN +++++++++++++++++++++++++++++++

const alteEffekte = findeSchalenEffekte(casterActor);

if (alteEffekte.length) {
    await casterActor.deleteEmbeddedDocuments(
        "ActiveEffect",
        alteEffekte.map(effect => effect.id)
    );
}

// +++ 7 - EFFEKT ÜBER BLOCK 6 ++++++++++++++++++++++++++++++++

const effektName = `${vollerName} - ${behaeltnis.name}`;

const changes = [
    {
        key: "system.skillModifiers.FW",
        mode: 0,
        value: `Kochen ${bonus}`,
        priority: 20
    },
    {
        key: "system.creatureBonus",
        mode: 0,
        value: `Gift -${bonus} Stufen`,
        priority: 20
    }
];

const effekt = await DSK_FW.Effekt.Anwenden({
    name: effektName,
    ahne,

    beschreibung:
        wirkungText +
        `<br><br><b>Geweihtes Behältnis:</b> ${behaeltnis.name}` +
        `<br><b>Wirkungsdauer:</b> ${dauerText}`,

    gabeZiel: "",
    qs,
    ziel: casterActor,
    changes,
    origin: casterActor.uuid,
    showIcon: 1,

    flags: {
        dsk: {
            isNurtisSchale: true,
            casterUuid: casterActor.uuid,
            qs,
            bonus,
            gegenstandId: behaeltnis.id,
            gegenstandName: behaeltnis.name,

            wirkungsende: {
                sfName: endeKey,
                basisEffektName: vollerName,
                beschreibungFuerEnde: endeText
            }
        }
    }
});

if (!effekt) {
    await raeumeQSAuf(casterActor);

    return ui.notifications.error(
        "Luna sagt 🌙: Nurtis Schale konnte nicht angelegt werden!"
    );
}

// +++ 8 - EFFEKT KONTROLLIEREN ++++++++++++++++++++++++++++++++

const endeDaten =
    effekt.getFlag("dsk", "wirkungsende");

const kochenKorrekt =
    (effekt.changes || []).some(change =>
        change.key === "system.skillModifiers.FW" &&
        Number(change.mode) === 0 &&
        change.value === `Kochen ${bonus}`
    );

const giftKorrekt =
    (effekt.changes || []).some(change =>
        change.key === "system.creatureBonus" &&
        Number(change.mode) === 0 &&
        change.value === `Gift -${bonus} Stufen`
    );

const erfolgreich =
    (effekt.name || effekt.label || "") === effektName &&
    effekt.getFlag("dsk", "isNurtisSchale") === true &&
    effekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
    effekt.getFlag("dsk", "gegenstandId") === behaeltnis.id &&
    effekt.getFlag("dsk", "gegenstandName") === behaeltnis.name &&
    Number(effekt.getFlag("dsk", "qs")) === qs &&
    Number(effekt.getFlag("dsk", "bonus")) === bonus &&
    endeDaten?.sfName === endeKey &&
    endeDaten?.basisEffektName === vollerName &&
    endeDaten?.beschreibungFuerEnde === endeText &&
    kochenKorrekt &&
    giftKorrekt;

if (!erfolgreich) {
    await effekt.delete().catch(() => {});
    await raeumeQSAuf(casterActor);

    return ui.notifications.error(
        "Luna sagt 🌙: Nurtis Schale wurde nicht vollständig angelegt!"
    );
}

// +++ 9 - ÖFFENTLICHE GABENKARTE ++++++++++++++++++++++++++++++

await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName,
    ahne,
    beschreibung: wirkungText,
    wirkender: casterName,

    ziele: [{
        name: behaeltnis.name,
        rolle: "Geweihtes Behältnis"
    }],

    misserfolge: [],
    dauerText,
    gmBereich: false,
    angewendet: true,
    erfolgreich: true,
    anfragenderUserId: game.user.id
});

// +++ 10 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++++++

await raeumeQSAuf(casterActor);

ui.notifications.info(
    `Luna sagt 🌙: ${behaeltnis.name} wurde zu Nurtis Schale.`
);

}).call(this);
